 const human=await loader.loadAsync(manifest.character);const visual=human.scene;normalize(visual,1.8);model=new THREE.Group();model.add(visual);actors.add(model);model.position.set(0,0,1.3);visual.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});
 mixer=new THREE.AnimationMixer(visual);const clips=human.animations;const idleClip=clips.find(c=>/idle|stand/i.test(c.name))||clips[0];const walkClip=clips.find(c=>/walk/i.test(c.name))||clips.find(c=>/run/i.test(c.name));idle=idleClip?mixer.clipAction(idleClip):null;walk=walkClip?mixer.clipAction(walkClip):null;idle?.play();mixer.update(.01);scene.updateMatrixWorld(true);visual.position.y-=new THREE.Box3().setFromObject(visual,true).min.y;
 const shadowCanvas=document.createElement('canvas');shadowCanvas.width=shadowCanvas.height=128;const ctx=shadowCanvas.getContext('2d'),g=ctx.createRadialGradient(64,64,4,64,64,62);g.addColorStop(0,'rgba(12,8,4,.36)');g.addColorStop(1,'rgba(12,8,4,0)');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);const shadow=new THREE.Mesh(new THREE.PlaneGeometry(1.35,1.35),new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(shadowCanvas),transparent:true,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.04;model.add(shadow);
