function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);if(mode==='a')controls.update();if(ready){if(walking){const d=target.clone().sub(model.position);d.y=0;if(d.length()<.05){walking=false;setAnimation(false);}else{const step=Math.min(d.length(),dt*1.1);d.normalize();model.position.addScaledVector(d,step);model.rotation.y=Math.atan2(d.x,d.z);}}mixer?.update(dt);let calls=0,triangles=0;if(mode==='b'&&baked){r.autoClear=true;r.render(bgScene,bgCamera);calls+=r.info.render.calls;triangles+=r.info.render.triangles;const old=scene.background;scene.background=null;set.visible=false;r.autoClear=false;r.render(scene,camera);set.visible=true;scene.background=old;r.autoClear=true;}else{set.visible=true;r.render(scene,camera);}calls+=r.info.render.calls;triangles+=r.info.render.triangles;const now=performance.now();frames.push(now-last);last=now;if(frames.length>120)frames.shift();window.MOCK.metrics={calls,triangles,frameMs:frames.reduce((a,b)=>a+b,0)/frames.length};$('stats').textContent=`${mode==='a'?'3D SCENE':'CACHED BACKGROUND'} · ${calls} draws · ${triangles.toLocaleString()} triangles`;}}
